export const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguageState] = useState(() => {
    if (typeof window === 'undefined') return 'en';
    try {
      const saved = window.localStorage.getItem('quickmeds-rx-language');
      return SUPPORTED_LANGUAGES.some((item) => item.code === saved) ? saved : 'en';
    } catch {
      return 'en';
    }
  });

  const setLanguage = useCallback((nextLanguage) => {
    if (!SUPPORTED_LANGUAGES.some((item) => item.code === nextLanguage)) return;
    setLanguageState(nextLanguage);
    void apiClient.put('/api/v1/profile/language', { preferredLanguage: nextLanguage }).catch(() => {
      // Anonymous browsing is supported; the device preference remains active locally.
    });
    if (typeof window !== 'undefined') {
      try {
        window.localStorage.setItem('quickmeds-rx-language', nextLanguage);
      } catch {
        // Keep the in-memory language change even when storage is unavailable.
      }
    }
  }, []);

  useEffect(() => {
    document.documentElement.lang = language;
    document.title = 'QuickMeds Rx';
  }, [language]);

  const t = useCallback((key) => messages[language]?.[key] ?? messages.en[key] ?? key, [language]);
  const value = useMemo(() => ({ language, setLanguage, t, languages: SUPPORTED_LANGUAGES }), [language, setLanguage, t]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

const defaultLanguageFallback = {
  language: 'en',
  setLanguage: () => {},
  t: (key) => messages['en']?.[key] ?? key,
  languages: SUPPORTED_LANGUAGES
};

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) {
    return defaultLanguageFallback;
  }
  return context;
}

export const useTranslation = useLanguage;
export default LanguageProvider;